// Obtenemos todos los items de entrada en el formato de n8n
const items = $input.all();

// Objeto para llevar el registro del ID más alto por cada número de teléfono
const phoneMap = {};

for (const item of items) {
  // Tomamos el celular; si está vacío, intentamos con el teléfono fijo.
  // Si no hay ninguno, usamos el ID para no borrar leads sin teléfono.
  const phone = item.json.pilot_cellphone || item.json.pilot_phone || `no-phone-${item.json.id}`;

  // Si el teléfono no está en el mapa, o el ID actual es mayor al que ya guardamos, lo actualizamos
  if (!phoneMap[phone] || item.json.id > phoneMap[phone].json.id) {
    phoneMap[phone] = item;
  }
}

// Convertimos el mapa de vuelta al formato de array que requiere n8n
return Object.values(phoneMap);

const item = $("Loop Over Items1").first().json;

// --------------------------------------------------
// NORMALIZAR TELÉFONO
// --------------------------------------------------
function normalizarTelefono(telefono) {
  // Solo dígitos, sin el 00 internacional
  let numero = String(telefono || "").replace(/\D/g, "");
  if (numero.startsWith("00")) numero = numero.slice(2);

  if (/^57\d{10}$/.test(numero)) return numero;         // Colombia con código: 573163127436
  if (/^3\d{9}$/.test(numero)) return "57" + numero;    // Celular Colombia: 3163127436 -> 573163127436
  if (/^54\d{10,11}$/.test(numero)) return numero;      // Argentina con código (pruebas): 5491131438902
  if (/^11\d{8}$/.test(numero)) return "549" + numero;  // Argentina CABA sin código (pruebas): 1131438902

  // Cualquier otro formato es inválido: no se inventa el país
  return "";
}

// --------------------------------------------------
// NORMALIZAR TELÉFONOS
// --------------------------------------------------
item.pilot_phone = normalizarTelefono(item.pilot_phone);
item.pilot_cellphone = normalizarTelefono(item.pilot_cellphone);

// --------------------------------------------------
// DATOS
// --------------------------------------------------
const nombre = item.pilot_firstname && item.pilot_lastname
  ? `${item.pilot_firstname} ${item.pilot_lastname}`
  : item.pilot_firstname || item.pilot_lastname || "No aclarado";

const modelo = item.pilot_product_of_interest || "No aclarado";

const imagen = "ford_mensajeria_20261002_102302.jpg";

const idQuery = String(item.id || "0");

// --------------------------------------------------
// CONTENT VARIABLES
// --------------------------------------------------
const variables = {
  "1": nombre,
  "2": modelo,
  "3": imagen,
  "4": idQuery
};

// --------------------------------------------------
// TEMPLATE
// --------------------------------------------------
const template_id = "HX7d117616da551b021f9c37b6b73b7257";

// --------------------------------------------------
// DEVOLVER
// --------------------------------------------------
return [
  {
    json: {
      ContentVariables: JSON.stringify(variables),
      template_id: template_id,

      // Mantener todos los datos originales
      ...item,

      debug: {
        nombreOriginal: nombre,
        modeloOriginal: modelo,
        imagenSeleccionada: imagen,
        idQuery: idQuery,
        telefono: item.pilot_cellphone || item.pilot_phone || ""
      }
    }
  }
];

